 * Usage:
 *   node slack_create_channel.cjs --name <name> [--private] [--dry-run]
 */

const { getToken, parseArgs, slackFetch, dryRun } = require('./slack_common.cjs');

const USAGE = 'Usage: node slack_create_channel.cjs --name <name> [--private] [--dry-run]';

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const name = args.name;
  if (!name) {
    console.error(USAGE);
    process.exit(2);
  }

