'use strict';
// Test suite for the slack-api skill scripts: syntax checks, --dry-run happy
// paths, and argument/token error paths. No network calls are made.
const { spawnSync } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');

const SCRIPTS = path.resolve('slack-api/scripts');
let pass = 0;
let fail = 0;

function record(name, ok, extra) {
  if (ok) {
    pass += 1;
    console.log(`PASS: ${name}`);
  } else {
    fail += 1;
    console.log(`FAIL: ${name}${extra ? ` -- ${extra}` : ''}`);
  }
}

function run(script, args, opts = {}) {
  const env = { ...process.env };
  if (opts.token === undefined) env.SLACK_TOKEN = 'xoxb-test-token';
  else if (opts.token === null) delete env.SLACK_TOKEN;
  else env.SLACK_TOKEN = opts.token;
  const res = spawnSync(process.execPath, [path.join(SCRIPTS, script), ...args], {
    encoding: 'utf8',
    env,
    timeout: 30000,
  });
  return { code: res.status, out: res.stdout || '', err: res.stderr || '' };
}

// --- syntax checks ---
const scriptFiles = fs.readdirSync(SCRIPTS).filter((f) => f.endsWith('.cjs'));
for (const f of scriptFiles) {
  const r = spawnSync(process.execPath, ['--check', path.join(SCRIPTS, f)], { encoding: 'utf8' });
  record(`syntax: ${f}`, r.status === 0, r.stderr);
}

// --- dry runs (happy paths, no network) ---
let r = run('slack_post_message.cjs', ['--channel', '#general', '--text', 'Hello <@U1234>', '--dry-run']);
record(
  'post_message dry run',
  r.code === 0 && r.out.includes('chat.postMessage') && r.out.includes('channel=#general') && r.out.includes('Hello <@U1234>'),
  `code=${r.code} out=${JSON.stringify(r.out)}`,
);

const blocksFile = path.join(os.tmpdir(), `blocks-${process.pid}.json`);
fs.writeFileSync(blocksFile, JSON.stringify([{ type: 'header', text: { type: 'plain_text', text: 'Hi' } }]));
r = run('slack_post_message.cjs', ['--channel', 'C123', '--blocks', blocksFile, '--dry-run']);
record('post_message --blocks dry run', r.code === 0 && r.out.includes('blocks='), `code=${r.code} out=${JSON.stringify(r.out)}`);
fs.rmSync(blocksFile, { force: true });

r = run('slack_post_message.cjs', ['--channel', '#general', '--text', 'later', '--post-at', '1710000000', '--dry-run']);
record(
  'post_message schedule dry run',
  r.code === 0 && r.out.includes('chat.scheduleMessage') && r.out.includes('post_at=1710000000'),
  `code=${r.code} out=${JSON.stringify(r.out)}`,
);

r = run('slack_list_channels.cjs', ['--dry-run']);
record('list_channels dry run', r.code === 0 && r.out.includes('conversations.list'), `code=${r.code} out=${JSON.stringify(r.out)}`);

r = run('slack_get_channel_history.cjs', ['--channel', 'C123', '--limit', '5', '--dry-run']);
record(
  'history dry run',
  r.code === 0 && r.out.includes('conversations.history') && r.out.includes('limit=5'),
  `code=${r.code} out=${JSON.stringify(r.out)}`,
);

r = run('slack_get_thread_replies.cjs', ['--channel', 'C123', '--thread-ts', '1710000000.123456', '--dry-run']);
record(
  'thread replies dry run',
  r.code === 0 && r.out.includes('conversations.replies') && r.out.includes('ts=1710000000.123456'),
  `code=${r.code} out=${JSON.stringify(r.out)}`,
);

r = run('slack_create_channel.cjs', ['--name', 'project-alpha', '--private', '--dry-run']);
record(
  'create channel dry run',
  r.code === 0 && r.out.includes('conversations.create') && r.out.includes('name=project-alpha') && r.out.includes('is_private=true'),
  `code=${r.code} out=${JSON.stringify(r.out)}`,
