#!/usr/bin/env node
'use strict';

/**
 * Shared helpers for the slack-api skill scripts.
 * - Reads the SLACK_TOKEN environment variable (never accept tokens as args).
 * - Calls the Slack Web API with form-encoded POST bodies.
 * - Supports --dry-run to print a request without sending it.
 * - Exits with concise, LLM-friendly messages (no stack traces).
 */

const BASE_URL = 'https://slack.com/api';

function getToken() {
  const token = process.env.SLACK_TOKEN;
  if (!token) {
    console.error('Error: SLACK_TOKEN environment variable is not set.');
    console.error('Export a bot token (xoxb-...) or user token (xoxp-...) with the required scopes.');
    process.exit(2);
  }
  return token;
}

// Parse argv: `--key value` pairs and `--flag` booleans. Returns { key: value }.
function parseArgs(argv) {
  const out = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (!a.startsWith('--')) continue;
    const key = a.slice(2);
    const next = argv[i + 1];
    if (next !== undefined && !next.startsWith('--')) {
      out[key] = next;
      i++;
    } else {
      out[key] = true;
    }
  }
  return out;
}

// POST a form-encoded request to the Slack Web API and return parsed JSON.
// Exits 1 with a concise message when the request fails or Slack returns ok:false.
async function slackFetch(token, method, params) {
  const body = new URLSearchParams(params);
  const res = await fetch(`${BASE_URL}/${method}`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}` },
    body,
  });
  if (!res.ok) {
    console.error(`Error: Slack API returned HTTP ${res.status} for ${method}.`);
    if (res.status === 429) {
      const retryAfter = res.headers.get('retry-after');
      console.error(`Rate limited; retry after ${retryAfter ? `${retryAfter}s` : 'a short delay'}.`);
    }
    process.exit(1);
  }
  const json = await res.json();
  if (!json.ok) {
    const err = json.error || 'unknown_error';
    console.error(`Error: Slack API ${method} failed: ${err}`);
    if (json.needed) console.error(`Required scopes: ${json.needed}`);
    process.exit(1);
  }
  return json;
}

// Print the request that would be sent, then exit 0 without sending anything.
function dryRun(method, params) {
  console.log(`[dry-run] POST ${BASE_URL}/${method}`);
  for (const [k, v] of Object.entries(params)) {
    if (k === 'token') continue;
    console.log(`  ${k}=${v}`);
  }
  console.log('[dry-run] No request was sent.');
  process.exit(0);
}

module.exports = { BASE_URL, getToken, parseArgs, slackFetch, dryRun };

#!/usr/bin/env node
'use strict';

/**
 * Post (or schedule) a message to a Slack channel, optionally in a thread
 * and/or with a Block Kit layout from a JSON file.
 *
 * Usage:
 *   node slack_post_message.cjs --channel <#name|C123> (--text "..." | --blocks file.json)
 *       [--thread-ts TS] [--post-at TS] [--dry-run]
 */

const fs = require('fs');
const { getToken, parseArgs, slackFetch, dryRun } = require('./slack_common.cjs');

const USAGE =
  'Usage: node slack_post_message.cjs --channel <#name|C123> (--text "..." | --blocks file.json) [--thread-ts TS] [--post-at TS] [--dry-run]';

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const channel = args.channel;
  const text = args.text;

  if (!channel) {
    console.error(USAGE);
    process.exit(2);
  }
  if (!text && !args.blocks) {
    console.error('Error: provide --text and/or --blocks.');
    process.exit(2);
  }

  const params = { channel };
  if (text) params.text = text;
  if (args['thread-ts']) params.thread_ts = args['thread-ts'];
  if (args.blocks) {
    let blocks;
    try {
      blocks = JSON.parse(fs.readFileSync(args.blocks, 'utf8'));
    } catch (e) {
      console.error(`Error: cannot read or parse blocks file "${args.blocks}": ${e.message}`);
      process.exit(2);
    }
    if (!Array.isArray(blocks)) {
      console.error('Error: blocks file must contain a JSON array of block objects.');
      process.exit(2);
    }
    params.blocks = JSON.stringify(blocks);
  }
  if (args['post-at']) params.post_at = String(args['post-at']);

  const token = getToken();
  const method = params.post_at ? 'chat.scheduleMessage' : 'chat.postMessage';
  if (args['dry-run']) dryRun(method, params);

  const json = await slackFetch(token, method, params);
  const target = json.channel ? json.channel.name || json.channel : channel;
  console.log(`Success: message ${params.post_at ? 'scheduled' : 'sent'} to ${target}`);
  console.log(`  ts: ${json.ts}`);
  if (json.message && json.message.text) console.log(`  text: ${json.message.text}`);
}

main().catch((e) => {
  console.error(`Error: ${e.message}`);
  process.exit(1);
});

#!/usr/bin/env node
'use strict';

/**
 * List Slack channels (public by default), paging automatically.
 *
 * Usage:
 *   node slack_list_channels.cjs [--types public_channel,private_channel] [--limit N]
 *       [--max N] [--include-archived] [--cursor C] [--dry-run]
 */

const { getToken, parseArgs, slackFetch, dryRun } = require('./slack_common.cjs');

const USAGE =
  'Usage: node slack_list_channels.cjs [--types public_channel,private_channel] [--limit N] [--max N] [--include-archived] [--cursor C] [--dry-run]';

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const params = {
    types: args.types || 'public_channel',
    limit: String(args.limit || '200'),
    exclude_archived: args['include-archived'] ? 'false' : 'true',
  };
  if (args.cursor) params.cursor = String(args.cursor);

  const token = getToken();
  if (args['dry-run']) dryRun('conversations.list', params);

  let cursor = params.cursor;
  let total = 0;
  const max = Number(args.max || '1000');
  do {
    if (cursor) params.cursor = cursor;
    const json = await slackFetch(token, 'conversations.list', params);
    for (const c of json.channels || []) {
      total += 1;
      const members = c.num_members !== undefined ? c.num_members : '?';
      console.log(`${c.id}\t#${c.name}\tprivate=${c.is_private}\tarchived=${c.is_archived}\tmembers=${members}`);
    }
    cursor = (json.response_metadata && json.response_metadata.next_cursor) || '';
    if (total >= max) {
      console.log(`Reached --max ${max} channels; pass --cursor "${cursor}" to continue.`);
      break;
    }
  } while (cursor);

  console.log(`Success: listed ${total} channel(s).`);
}

main().catch((e) => {
  console.error(`Error: ${e.message}`);
  process.exit(1);
});

#!/usr/bin/env node
'use strict';

/**
 * Read message history from a Slack channel, paging automatically.
 *
 * Usage:
 *   node slack_get_channel_history.cjs --channel <C123> [--limit N] [--max N]
 *       [--oldest TS] [--latest TS] [--inclusive] [--dry-run]
 */

const { getToken, parseArgs, slackFetch, dryRun } = require('./slack_common.cjs');

const USAGE =
  'Usage: node slack_get_channel_history.cjs --channel <C123> [--limit N] [--max N] [--oldest TS] [--latest TS] [--inclusive] [--dry-run]';

function oneLine(s) {
  return String(s || '').replace(/\s+/g, ' ').trim();
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const channel = args.channel;
  if (!channel) {
    console.error(USAGE);
    process.exit(2);
  }

  const params = { channel, limit: String(args.limit || '20') };
  if (args.oldest) params.oldest = String(args.oldest);
  if (args.latest) params.latest = String(args.latest);
  if (args.inclusive) params.inclusive = 'true';

  const token = getToken();
  if (args['dry-run']) dryRun('conversations.history', params);

  let cursor = '';
  let total = 0;
  const max = Number(args.max || '200');
  do {
    if (cursor) params.cursor = cursor;
    const json = await slackFetch(token, 'conversations.history', params);
    for (const m of json.messages || []) {
      total += 1;
      const who = m.user || m.subtype || '-';
      const thread = m.thread_ts ? `\tthread=${m.thread_ts}` : '';
      console.log(`${m.ts}\t${who}\t${oneLine(m.text)}${thread}`);
    }
    cursor = (json.response_metadata && json.response_metadata.next_cursor) || '';
    if (total >= max) {
      console.log(`Reached --max ${max} messages; pass --cursor "${cursor}" to continue.`);
      break;
    }
  } while (cursor);

  console.log(`Success: fetched ${total} message(s) from ${channel}.`);
}

main().catch((e) => {
  console.error(`Error: ${e.message}`);
  process.exit(1);
});

