#!/usr/bin/env node
'use strict';

/**
 * Upload a file to Slack channel(s) using files.upload (multipart/form-data).
 *
 * Usage:
 *   node slack_upload_file.cjs --file <path> --channels <#general,C123>
 *       [--title T] [--initial-comment C] [--dry-run]
 */

const fs = require('fs');
const path = require('path');
const { BASE_URL, getToken, parseArgs } = require('./slack_common.cjs');

const USAGE =
  'Usage: node slack_upload_file.cjs --file <path> --channels <#general,C123> [--title T] [--initial-comment C] [--dry-run]';

const MIME_BY_EXT = {
  '.pdf': 'application/pdf',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.csv': 'text/csv',
  '.txt': 'text/plain',
  '.md': 'text/markdown',
  '.json': 'application/json',
  '.zip': 'application/zip',
};

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const filePath = args.file;
  const channels = args.channels;
  if (!filePath || !channels) {
    console.error(USAGE);
    process.exit(2);
  }

  let buf;
  try {
    buf = fs.readFileSync(filePath);
  } catch (e) {
    console.error(`Error: cannot read file "${filePath}": ${e.message}`);
    process.exit(2);
  }
  const filename = path.basename(filePath);
  const mime = MIME_BY_EXT[path.extname(filePath).toLowerCase()] || 'application/octet-stream';

  const token = getToken();
  if (args['dry-run']) {
    console.log(`[dry-run] POST ${BASE_URL}/files.upload (multipart/form-data)`);
    console.log(`  file=${filename} (${buf.length} bytes, ${mime})`);
    console.log(`  channels=${channels}`);
    if (args.title) console.log(`  title=${args.title}`);
    if (args['initial-comment']) console.log(`  initial_comment=${args['initial-comment']}`);
    console.log('[dry-run] No request was sent.');
    process.exit(0);
  }

  const form = new FormData();
  form.append('channels', channels);
  form.append('file', new Blob([buf], { type: mime }), filename);
  if (args.title) form.append('title', args.title);
  if (args['initial-comment']) form.append('initial_comment', args['initial-comment']);

  const res = await fetch(`${BASE_URL}/files.upload`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}` },
    body: form,
  });
  if (!res.ok) {
    console.error(`Error: Slack API returned HTTP ${res.status} for files.upload.`);
    process.exit(1);
  }
  const json = await res.json();
  if (!json.ok) {
    console.error(`Error: Slack API files.upload failed: ${json.error || 'unknown_error'}`);
    if (json.needed) console.error(`Required scopes: ${json.needed}`);
    process.exit(1);
  }
  const f = json.file || {};
  console.log(`Success: uploaded "${f.name || filename}" (id ${f.id}) to ${channels}`);
  if (f.permalink) console.log(`  permalink: ${f.permalink}`);
}

main().catch((e) => {
  console.error(`Error: ${e.message}`);
  process.exit(1);
});

#!/usr/bin/env node
'use strict';

/**
 * Look up a Slack user by their email address (users.lookupByEmail).
 *
 * Usage:
 *   node slack_lookup_user.cjs --email <addr> [--dry-run]
 */

const { getToken, parseArgs, slackFetch, dryRun } = require('./slack_common.cjs');

const USAGE = 'Usage: node slack_lookup_user.cjs --email <addr> [--dry-run]';

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const email = args.email;
  if (!email) {
    console.error(USAGE);
    process.exit(2);
  }

  const params = { email };

  const token = getToken();
  if (args['dry-run']) dryRun('users.lookupByEmail', params);

  const json = await slackFetch(token, 'users.lookupByEmail', params);
  const u = json.user || {};
  const display = (u.profile && u.profile.display_name) || u.real_name || u.name;
  console.log(`Success: ${u.real_name || u.name} (${display}) ${u.id} <${email}>`);
}

main().catch((e) => {
  console.error(`Error: ${e.message}`);
  process.exit(1);
});

# Block Kit

Block Kit produces rich, structured messages: headers, sections with fields, buttons, dividers, context lines, and images. Pass a JSON array of block objects to `--blocks <file>` with `slack_post_message.cjs`.

## Rules

- The top level is a JSON array; maximum 50 blocks per message.
- Every block requires a `"type"`. Text objects inside blocks require `"type": "mrkdwn"` or `"type": "plain_text"` plus `"text"`.
- `mrkdwn` text supports the same formatting as plain message text.
- Section text: max 3000 characters; field values: max 2000 characters.

## Common blocks

```json
{"type": "header", "text": {"type": "plain_text", "text": "Announcement"}}
{"type": "section", "text": {"type": "mrkdwn", "text": "*Big news* for <#C123|team>"}}
{"type": "section", "fields": [
  {"type": "mrkdwn", "text": "*Status:*\nDone"},
  {"type": "mrkdwn", "text": "*Owner:*\n<@U1234>"}
]}
{"type": "divider"}
{"type": "context", "elements": [{"type": "mrkdwn", "text": "Posted by <@U1234>"}]}
{"type": "actions", "elements": [
  {"type": "button", "text": {"type": "plain_text", "text": "Approve"}, "style": "primary", "value": "approve"}
]}
```

## Templates

Ready-to-use templates live in `assets/blocks/`:

- `announcement.json` — header + section + context
- `header_section.json` — header + fields + divider + action buttons

Copy a template, edit the text, and pass it to `--blocks`.

[
  { "type": "header", "text": { "type": "plain_text", "text": "Announcement" } },
  { "type": "section", "text": { "type": "mrkdwn", "text": "Replace this with the announcement text." } },
  { "type": "context", "elements": [ { "type": "mrkdwn", "text": "Posted by <@U1234>" } ] }
]

[
  { "type": "header", "text": { "type": "plain_text", "text": "Weekly report" } },
  { "type": "section", "fields": [
    { "type": "mrkdwn", "text": "*Status:*\nOn track" },
    { "type": "mrkdwn", "text": "*Owner:*\n<@U1234>" }
  ] },
  { "type": "divider" },
  { "type": "actions", "elements": [
    { "type": "button", "text": { "type": "plain_text", "text": "Approve" }, "style": "primary", "value": "approve" },
    { "type": "button", "text": { "type": "plain_text", "text": "Request changes" }, "value": "changes" }
  ] }
]

